const raw = $('Retell Tool Call').first().json.body || $('Retell Tool Call').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  body = raw;
}

const nombre = String(body.nombre || '').trim();
const telefono = String(body.telefono || '').trim();
const sede = String(body.sede || '').trim();
const servicio = String(body.servicio || '').trim();
const fecha = String(body.fecha || '').trim();
const hora = String(body.hora || '').trim();
const notas = String(body.notas || '').trim();
// Aceptar tanto 'empleado' como 'staff_member' (como usa el prompt de Retell)
const empleadoInput = String(body.empleado || body.staff_member || '').trim();
const empleado = empleadoInput;

// Location IDs
const LOCATION_IDS = {
  'collado_villalba': '4159c713-3507-49ba-8319-c4b7ed4f38b2',
  'alpedrete': '61865f3b-976b-427b-b5f1-c856e7b97cdf'
};

// Calendarios por empleado (búsqueda por nombre)
const CALENDARIOS_EMPLEADOS = {
  // Collado
  'fernando': '06136cb5016a75da20e0292649097ca53d818c3145984831dda2d02311d929f4@group.calendar.google.com',
  'almudena': 'aade57f8bb3504fdc3582de697f8892c71817b94a2e32cebf8a891d8a1d48c2b@group.calendar.google.com',
  'johanna': 'c35d85ddf7afa97e4edb360ef99552b6289a2d95e9b939745bff7505557b73e2@group.calendar.google.com',
  'isabel': 'df5a40b3c772d155e8451db37483283cb815d71914dfd7af21750266da3eec48@group.calendar.google.com',
  'tania': '3e70700c207422d765f314fa80988edf99922c02bca81b62e0398347e15be65c@group.calendar.google.com',
  'macarena': '293331e0b723181277b20c87228b119f9701886dd1d3645a2747c7ee22b850e8@group.calendar.google.com',
  'alí': '01dabb00d1abb92b2313be55204645f2a6862e37f18779821045f3b1874250e1@group.calendar.google.com',
  'maria': '968ca744f4a0356d6948ae097d54127b373c9cc5efcc889479381101773ee8e7@group.calendar.google.com',
  'maria2': 'd70f48f63430635525a6ad0e7f835a32ae68a6e77aeb74810fd8ba9c4de836a2@group.calendar.google.com',
  'marian': '4cace839a6b98a4c7f5c910f4e898c1e0ebda5712c45939783b8e720543c9d5e@group.calendar.google.com',
  // Alpedrete
  'ana': '7ced6d3e137d513c4cc58b517ad1fa344efbb883cdd3dbce8fd0046ac053c924@group.calendar.google.com',
  'cristina': '62b7d9a94d9f7a745d1d7c65448838ceecaa5ab4e999e3ace21546c913f7a710@group.calendar.google.com'
};

// Duraciones por servicio (minutos)
const DURACIONES = {
  'Corte Señora': 45, 'Corte Caballero': 30, 'Corte flequillo': 10,
  'Meches completas': 90, 'Balayage': 90, 'Babylight': 90,
  'Tinte raíz': 60, 'Color Raíz': 60, 'Baño de color': 60,
  'Tratamiento Keratina': 90, 'Alisado': 160, 'Permanente': 90,
  'Manicura': 30, 'Manicura semipermanente': 45,
  'Pedicura': 45, 'Pedicura semipermanente': 60,
  'Cejas': 15, 'Depilación axilas': 10, 'Depilación piernas': 30
};

const duracion = DURACIONES[servicio] || 60;

// Calcular fechas
const fechaInicio = new Date(`${fecha}T${hora}:00`);
const fechaFin = new Date(fechaInicio.getTime() + duracion * 60000);

// Formatear para mensajes
const diasSemana = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];
const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const diaSemana = diasSemana[fechaInicio.getUTCDay()];
const diaMes = fechaInicio.getUTCDate();
const mes = meses[fechaInicio.getUTCMonth()];

// Título del evento
const apellido = nombre.split(' ').pop();
const tituloEvento = `${nombre} - ${servicio} (${sede.replace('_', ' ')})${empleado ? ' con ' + empleado : ''}`;

// Descripción con todos los datos
const descripcion = `Cliente: ${nombre}\nTeléfono: ${telefono}\nServicio: ${servicio}\nDuración: ${duracion} min${empleado ? '\nEmpleada: ' + empleado : ''}${notas ? '\nNotas: ' + notas : ''}`;

// Determinar calendario: empleado específico o primary por defecto
const empleadoLower = empleado.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
let calendarId = 'primary';

// Búsqueda exacta primero
if (empleado && CALENDARIOS_EMPLEADOS[empleadoLower]) {
  calendarId = CALENDARIOS_EMPLEADOS[empleadoLower];
} else if (empleado && empleado.length >= 2) {
  // Búsqueda parcial: si "isa" está en "isabel", usar ese calendario
  // También maneja apodos: "Isa" → "Isabel", "Almu" → "Almudena", etc.
  for (const [nombreNorm, calId] of Object.entries(CALENDARIOS_EMPLEADOS)) {
    if (nombreNorm.includes(empleadoLower) || empleadoLower.includes(nombreNorm)) {
      calendarId = calId;
      break;
    }
  }
}

return [{ json: {
  nombre,
  telefono,
  sede,
  servicio,
  fecha,
  hora,
  notas,
  empleado,
  duracion,
  calendar_id: calendarId,
  location_id: LOCATION_IDS[sede],
  fechaInicio: fechaInicio.toISOString(),
  fechaFin: fechaFin.toISOString(),
  tituloEvento,
  descripcion,
  diaSemana,
  diaMes,
  mes,
  apellido
}}];

const gcalEvent = $('Google Calendar - Crear Evento').first().json;
const datos = $('Parsear Argumentos').first().json;

if (gcalEvent.id) {
  const mensajeConfirmacion = `Cita confirmada. Te esperamos el ${datos.diaSemana} ${datos.diaMes} de ${datos.mes} a las ${datos.hora} en ${datos.sede.replace('_', ' ')}.`;

  return [{
    json: {
      confirmado: true,
      id_cita: gcalEvent.id,
      google_calendar_id: gcalEvent.id,
      resumen: `${datos.nombre} - ${datos.servicio} el ${datos.diaSemana} ${datos.diaMes} de ${datos.mes} a las ${datos.hora}`,
      mensaje_confirmacion: mensajeConfirmacion,
      gcal_html_link: gcalEvent.htmlLink,
      empleado: datos.empleado,
      sede: datos.sede
    }
  }];
} else {
  return [{
    json: {
      confirmado: false,
      error: 'No se pudo crear el evento en Google Calendar',
      mensaje: 'Ha habido un problema al crear la cita. ¿Quieres que lo intentemos de nuevo?'
    }
  }];
}
